#[cfg(test)]
mod r6_cells_minus_tests {
    use super::*;
    mod bench;
    /// Every set of runs of the cells 0..6.
    fn all_sets() -> Vec<CellSet> {
        (0..1u32 << 6)
            .map(|m| cells_join((0..6).filter(|c| m >> c & 1 == 1).map(|c| (c, c)).collect()))
            .collect()
    }
    #[test]
    fn cells_without_is_the_cells_of_one_set_not_in_the_other() {
        let sets = all_sets();
        for a in &sets {
            for b in &sets {
                let cells: Vec<usize> = (0..6)
                    .filter(|&c| a.iter().any(|r| r.0 <= c && c <= r.1))
                    .filter(|&c| !b.iter().any(|r| r.0 <= c && c <= r.1))
                    .collect();
                let want = cells_join(cells.into_iter().map(|c| (c, c)).collect());
                assert_eq!(cells_without(a, b), want, "{a:?} minus {b:?}");
            }
        }
    }
    /// The small instances of the benchmark in `bench.rs`: each of `n` sets of two runs takes
    /// away all `n` points of `a` but one, which it holds.
    #[test]
    fn few_runs_taken_from_many_leave_the_rest() {
        for n in 1..=8usize {
            let a: CellSet = (0..n).map(|j| (2 * j, 2 * j)).collect();
            for j in 0..n {
                assert!(cells_without(&a, &[(0, 2 * j), (2 * j + 2, 2 * n)]).is_empty());
                assert_eq!(cells_without(&a, &[(2 * j + 1, 2 * n)]).len(), j + 1);
            }
        }
    }
}

#[cfg(test)]
mod r6_shared_window_tests {
    use super::*;
    mod bench;
    /// n holders, each the meet of two views of one shared set of n points through windows
    /// ending at `2n - j` and `2n - 2j`, each with a point of its own (distinct_extras_skew).
    fn skew(n: usize) -> Parts {
        let x = Atom::Sym("i".into());
        let xl = Lin::atom(x.clone());
        let c = |k: usize| Lin::constant(k as i128);
        let at = |k: usize| Con::eq(&xl, &c(k));
        let make = |cons: Vec<Con>, ors: Vec<Vec<Rc<Parts>>>| {
            let mut p = Parts::default();
            p.cons = cons;
            p.ors = ors;
            Rc::new(p)
        };
        let h = make(
            Vec::new(),
            vec![(0..n).map(|j| make(vec![at(2 * j)], Vec::new())).collect()],
        );
        let below = |k: usize| make(vec![Con::ge(&c(k), &xl)], vec![vec![h.clone()]]);
        let mut p = Parts::default();
        p.cons = vec![Con::ge(&xl, &c(0)), Con::ge(&c(8 * n), &xl)];
        p.ors.push(
            (0..n)
                .map(|j| {
                    let own = |k: usize| make(vec![at(k)], Vec::new());
                    let a = make(Vec::new(), vec![vec![below(2 * n - j), own(4 * n + 2 * j)]]);
                    let b = make(
                        Vec::new(),
                        vec![vec![below(2 * n - 2 * j), own(4 * n + 2 * j + 1)]],
                    );
                    make(Vec::new(), vec![vec![a], vec![b]])
                })
                .collect(),
        );
        p
    }
    /// The small instances of the benchmark in `bench.rs`.
    #[test]
    fn views_of_one_set_through_different_windows_have_a_point_at_small_sizes() {
        for n in 1..=8 {
            assert_eq!(has_point(skew(n)), Ok(true), "{n}");
        }
    }
    #[test]
    fn views_of_one_set_meet_as_their_runs() {
        let set = CellPiece::of(vec![(0, 0), (2, 3), (5, 5), (7, 9)]);
        let extras = [
            vec![],
            vec![(1, 1)],
            vec![(3, 6)],
            vec![(0, 10)],
            vec![(4, 4), (8, 11)],
        ];
        let mut views = Vec::new();
        for lo in 0..=10usize {
            for hi in lo.saturating_sub(1)..=10 {
                for e in &extras {
                    views.push(CellView {
                        main: set.clamp(lo, hi),
                        extra: CellPiece::of(e.clone()),
                    });
                }
            }
        }
        for a in &views {
            for b in &views {
                assert_eq!(a.meet(b).runs(), cells_meet(&a.runs(), &b.runs()));
            }
        }
    }
}

/// The two returns of [`cell_sweep`]'s `resolve_disj` that find a disjunction holds no cell of
/// its atom (PRES-unreached-3-left). Through [`decide`] both shapes are answered before the
/// sweep by [`by_cells`] without solving, whose walk finds the same disjunction dead; these
/// tests call the sweep directly.
#[cfg(test)]
mod cell_sweep_empty_tests {
    use super::*;

    fn var(s: &str) -> Lin {
        Lin::atom(Atom::Sym(s.into()))
    }

    fn part(cons: Vec<Con>, ors: Vec<Vec<Rc<Parts>>>) -> Rc<Parts> {
        let mut p = Parts::default();
        p.cons.extend(cons);
        p.ors.extend(ors);
        Rc::new(p)
    }

    /// `-6 <= i <= 6 && (lo1 <= i <= hi1 && (A || B) || lo2 <= i <= hi2 && (C || D))`, where
    /// each leaf `(lo, hi, v)` is `lo <= i <= hi && q == v`; `None` leaves the side open.
    type Leaf = (Option<i128>, Option<i128>, i128);
    fn guarded(guards: [(Option<i128>, Option<i128>); 2], leaves: [[Leaf; 2]; 2]) -> Parts {
        let i = var("i");
        let c = Lin::constant;
        let bounds = |lo: Option<i128>, hi: Option<i128>| {
            let mut v = Vec::new();
            if let Some(lo) = lo {
                v.push(Con::ge(&i, &c(lo)));
            }
            if let Some(hi) = hi {
                v.push(Con::ge(&c(hi), &i));
            }
            v
        };
        let mut p = Parts::default();
        p.cons = bounds(Some(-6), Some(6));
        let tops = guards
            .iter()
            .zip(leaves.iter())
            .map(|(&(lo, hi), pair)| {
                let inner = pair
                    .iter()
                    .map(|&(llo, lhi, v)| {
                        let mut cons = bounds(llo, lhi);
                        cons.push(Con::eq(&var("q"), &c(v)));
                        part(cons, Vec::new())
                    })
                    .collect();
                part(bounds(lo, hi), vec![inner])
            })
            .collect();
        p.ors.push(tops);
        p
    }

    #[test]
    fn a_disjunction_whose_every_disjunct_is_dead_inside_holds_no_cell() {
        // Each leaf lies outside -6..=6, so each top disjunct is dead: the first return.
        let p = guarded(
            [(None, Some(0)), (Some(1), None)],
            [
                [(Some(10), None, 1), (None, Some(-10), 2)],
                [(Some(11), None, 3), (None, Some(-11), 4)],
            ],
        );
        assert_eq!(cell_sweep::decide_by_cells(&p), Some(Ok(false)));
        assert_eq!(has_point(p), Ok(false));
    }

    #[test]
    fn a_disjunction_whose_leaves_lie_outside_their_guards_holds_no_cell() {
        // Each leaf meets -6..=6 but not the guard above it, so every top disjunct is live and
        // no cell is harvested: the second return.
        let p = guarded(
            [(Some(-1), Some(1)), (Some(2), Some(4))],
            [
                [(Some(3), None, 1), (None, Some(-3), 2)],
                [(Some(5), None, 3), (None, Some(1), 4)],
            ],
        );
        assert_eq!(cell_sweep::decide_by_cells(&p), Some(Ok(false)));
        assert_eq!(has_point(p), Ok(false));
    }
}

/// `slack::sweep_row_unbounded` against the search it stands for (PRES-unreached-3-left): on
/// random rows of 2 and 3 names, the arms it marks are those where `pick_by` finds a point with
/// the arm forced and the row's other disjunctions read in order, fast and not. The fast pattern
/// away from the greatest name is skipped where the other greatest name `gm` is not above the
/// name `xl` that takes the rest (`gm <= xl`: every row of 2 names, and in rows of 3 `gm == 1` at
/// `loc == 0` or `gm == 0` elsewhere); this checks that the other patterns find every point there.
#[cfg(test)]
mod sweep_against_pick_tests {
    use super::*;

    #[test]
    fn the_unbounded_row_sweep_marks_the_arms_pick_by_finds() {
        let mut seed: u64 = 0x5eed_1234;
        let mut below = |n: u64| {
            seed = seed
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (seed >> 33) % n
        };
        let mut skipped_hits = 0usize;
        let mut wrong = Vec::new();
        for _ in 0..1500 {
            let k = 2 + below(2) as usize;
            // Distinct names in a random order, so the greatest name falls anywhere in the row.
            let mut names: Vec<usize> = (0..k).collect();
            for i in (1..k).rev() {
                names.swap(i, below(i as u64 + 1) as usize);
            }
            let ws: Vec<i128> = (0..k).map(|_| 1 + below(5) as i128).collect();
            let highs: Vec<usize> = (0..k).map(|_| below(2) as usize).collect();
            let atom = |i: usize| Atom::Sym(format!("a{}", names[i]).into());
            let row = || -> Vec<DisjInfo> {
                (0..k)
                    .map(|i| DisjInfo {
                        disj_idx: i,
                        atom: atom(i),
                        low_arm: 1 - highs[i],
                        high_arm: highs[i],
                        low_val: Int::ZERO,
                        high_val: Int::from(ws[i]),
                        weight: Int::from(ws[i]),
                    })
                    .collect()
            };
            let arm = |i: usize, a: usize| -> Rc<Parts> {
                let v = if a == highs[i] { ws[i] } else { 0 };
                let mut d = Parts::default();
                d.cons.push(Con::eq(&Lin::atom(atom(i)), &Lin::constant(v)));
                Rc::new(d)
            };
            let by_name = |skip: Option<usize>| {
                (0..k)
                    .filter(|&i| Some(i) != skip)
                    .max_by_key(|&i| names[i])
                    .expect("two names or more")
            };
            let gmax1 = by_name(None);
            let gmax2 = by_name(Some(gmax1));
            let sum = (0..k).fold(Lin::constant(0), |s, i| s.plus(&Lin::atom(atom(i))));
            let total: i128 = ws.iter().sum();
            for target in 0..=total {
                let plan = sweep_row_unbounded(row(), Int::from(target), true);
                for loc in 0..k {
                    let gm = if loc == gmax1 { gmax2 } else { gmax1 };
                    let skipped = gm <= usize::from(loc == 0);
                    for a in 0..2 {
                        let mut q = Parts::default();
                        q.cons.push(Con::eq(&sum, &Lin::constant(target)));
                        for i in (0..k).filter(|&i| i != loc) {
                            q.ors.push(vec![arm(i, 0), arm(i, 1)]);
                        }
                        q.put(&arm(loc, a));
                        let fast = pick_by(&q, true, true).is_ok();
                        let slow = pick_by(&q, true, false).is_ok();
                        let swept = !matches!(plan.hit_table[loc][a], HitKind::None);
                        if swept != fast || swept != slow {
                            wrong.push(format!(
                                "names {names:?}, weights {ws:?}, high arms {highs:?}, target {target}, loc {loc}, arm {a}: sweep {swept}, fast {fast}, slow {slow}"
                            ));
                        }
                        skipped_hits += usize::from(skipped && swept);
                    }
                }
            }
        }
        // 10488 hits where the fast pattern is skipped on 2026-11-14, so the test does not
        // silently stop reaching them.
        assert!(skipped_hits > 0, "no hit where the fast pattern is skipped");
        assert!(
            wrong.is_empty(),
            "{} differ:\n{}",
            wrong.len(),
            wrong.join("\n")
        );
    }
}

#[cfg(test)]
mod loose_pair_tests {
    use super::*;

    fn c(terms: &[(&str, i64)], k: i64, rel: Rel) -> Con {
        Con {
            lin: Lin {
                terms: (terms.iter())
                    .map(|(s, c)| (Atom::Sym((*s).into()), Int::from(*c)))
                    .collect(),
                constant: Int::from(k),
            },
            rel,
        }
    }

    /// `a + 3·b + c + 1 == 0` and `3·a + 2·b + 3·c + 2 == 0` in the box `-4..=4`: the first is
    /// tied (`a` and `c` alike) and kept as two opposite rows; each step on the second, which
    /// has no unit coefficient, rewrites that pair, and the rewritten pair once met as a new
    /// equality, tied again, so the steps never ended (found by
    /// `exact::tests::random_formulas_project_to_the_values_of_their_points`). Three times the
    /// first minus the second is `7·b + 1 == 0`, so there is no point; without the box the
    /// solver found that at once, and with it ran for minutes.
    #[test]
    fn a_tied_equality_rewritten_is_not_met_again() {
        let mut cons = vec![
            c(&[("a", 1), ("b", 3), ("c", 1)], 1, Rel::Eq),
            c(&[("a", 3), ("b", 2), ("c", 3)], 2, Rel::Eq),
        ];
        assert_eq!(solve(&cons, true), Ok(None));
        for n in ["a", "b", "c"] {
            cons.push(c(&[(n, 1)], 4, Rel::Ge));
            cons.push(c(&[(n, -1)], 4, Rel::Ge));
        }
        assert_eq!(solve(&cons, true), Ok(None));
        assert_eq!(solve(&cons, false), Ok(None));
        // With the second equation moved to have points: `b == -1`, `a + c == 2`.
        cons[1] = c(&[("a", 3), ("b", 2), ("c", 3)], -4, Rel::Eq);
        let m = solve(&cons, true).unwrap().expect("a point");
        assert!(cons.iter().all(|k| k.holds(&m)), "{m:?}");
    }
}
